func (r *raft) selfRemoved() bool {
	if r.isObserver() {
		_, ok := r.observers[r.nodeID]
		return !ok
	}
	if r.isWitness() {
		_, ok := r.witnesses[r.nodeID]
		return !ok
	}
	_, ok := r.remotes[r.nodeID]
	return !ok
}

