	var notified bitmap
	for _, req := range mb.Requests {
		idx := wr.partitioner.GetPartitionID(req.ClusterId)
		readyMap := wr.maps[idx]
		readyMap.setClusterReady(req.ClusterId)
	}
	for _, req := range mb.Requests {
		idx := wr.partitioner.GetPartitionID(req.ClusterId)
		if !notified.contains(idx) {
			notified.add(idx)
			wr.notify(idx)
		}
